    explanation: '正しい。信託財産留保額は解約時のコストで、販売会社等の収入ではなく信託財産に残される。\nインデックスファンドなどのパッシブ運用はベンチマークへの連動を目指し、アクティブ運用はベンチマークを上回る成果を目指す。グロースは成長性、バリューは割安性に着目する。信託財産留保額は換金時に差し引かれ信託財産に残る。\n【図解】\n★投資信託の運用スタイル\n○パッシブ運用→ベンチマークに連動（コスト低）\n○アクティブ運用→ベンチマーク超えを目指す（コスト高）\n→トップダウン：マクロ分析から銘柄へ／ボトムアップ：個別企業分析の積上げ\n→グロース：成長性重視／バリュー：割安株重視\n⚠信託報酬＝保有中毎日差引き／信託財産留保額＝換金時に信託財産に残す',
